const $=id=>document.getElementById(id);let ws=null,myId=null,myName='',activeId=null,tab='chats',users=[],messagesByChat=new Map(),unreadCounts=new Map(),typingTimer=null,authMode='login',toastTimer=null,reconnectTimer=null,registrationId=null,smsStep=false,mediaRecorder=null,recordChunks=[],localStream=null,pc=null,callPeer=null,callType='audio',callInitiator=false,micMuted=false,cameraOff=false,pendingCandidates=[],pendingUploadTickets=new Map(),uploadInProgress=false,replyingTo=null,callId=null,callStartedAt=0,cookieStats={clicks:0,pulses:0},cookieCaptcha=null,reconnectDelay=1000,reconnectNoticeShown=false,manualDisconnect=false;
const globalKey='global',dmKey=id=>'dm:'+id,channelKey=id=>'channel:'+id;let channels=[],newsPosts=[],profileAvatarData='',channelComments=[],publicProfileId=null;
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function avatar(name){return esc((name||'?').trim().slice(0,1).toUpperCase())}
function avatarContent(name,data){return data?'<img alt="Аватар" loading="lazy" src="'+esc(data)+'">':avatar(name)}
function giftDecor(user){return (user?.equippedGifts||[]).slice(0,3).map(g=>'<span class="profile-gift" title="'+esc(g.name)+' · '+esc(g.rarity)+'"><span class="gift-layer-back">✦</span><span class="gift-layer-main">'+esc(g.emoji)+'</span><span class="gift-layer-spark">✧</span></span>').join('')}
function adminBadge(user){return user?.admin||user?.roleLabel?'<span class="admin-badge">✦ '+esc(user.roleLabel||(user.admin?'Admin':''))+'</span>':''}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
const pulseSoundPlayers={},pulseSoundUrls={};let pulseSoundContext=null,pulseSoundDBPromise=null;
const pulseSoundKeys={notification:'pulseNotificationSound',call:'pulseCallSound'};
function pulseSoundDB(){if(!pulseSoundDBPromise)pulseSoundDBPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('pulse-sound-storage',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('sounds'))req.result.createObjectStore('sounds')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('IndexedDB unavailable'))});return pulseSoundDBPromise}
async function storePulseSound(key,blob){const db=await pulseSoundDB();await new Promise((resolve,reject)=>{const tx=db.transaction('sounds','readwrite');tx.objectStore('sounds').put(blob,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('Не удалось сохранить звук'));tx.onabort=()=>reject(tx.error||new Error('Сохранение отменено'))})}
async function readPulseSound(key){const db=await pulseSoundDB();return new Promise((resolve,reject)=>{const req=db.transaction('sounds','readonly').objectStore('sounds').get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error||new Error('Не удалось прочитать звук'))})}
async function deletePulseSound(key){const db=await pulseSoundDB();await new Promise((resolve,reject)=>{const tx=db.transaction('sounds','readwrite');tx.objectStore('sounds').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('Не удалось удалить звук'))})}
async function initPulseSounds(){for(const [type,key] of Object.entries(pulseSoundKeys)){try{let blob=await readPulseSound(key);const legacy=localStorage.getItem(key);if(!blob&&legacy){blob=await (await fetch(legacy)).blob();await storePulseSound(key,blob);localStorage.removeItem(key)}if(blob)pulseSoundUrls[type]=URL.createObjectURL(blob)}catch(e){console.warn('Pulse sound storage:',e)} }updateSoundStatuses()}
function stopPulseSound(type){const p=pulseSoundPlayers[type];if(!p)return;if(p.audio){p.audio.pause();p.audio.currentTime=0}if(p.timer)clearInterval(p.timer);delete pulseSoundPlayers[type]}
function playPulseSound(type,loop=false){if(localStorage.getItem('pulseSounds')==='0')return;stopPulseSound(type);const custom=pulseSoundUrls[type];if(custom){const audio=new Audio(custom);audio.volume=.85;audio.loop=loop;pulseSoundPlayers[type]={audio};audio.play().catch(()=>{});return}try{const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;if(!pulseSoundContext)pulseSoundContext=new Ctx();const beep=()=>{if(!pulseSoundContext)return;const ctx=pulseSoundContext;ctx.resume().catch(()=>{});const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=type==='call'?620:880;gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.055,ctx.currentTime+.025);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.24);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.25)};beep();pulseSoundPlayers[type]={timer:loop?setInterval(beep,1350):null}}catch{}}
function updateSoundStatuses(){if($('notificationSoundStatus'))$('notificationSoundStatus').textContent=pulseSoundUrls.notification?'Свой звук выбран ✓':'Стандартный короткий сигнал';if($('callSoundStatus'))$('callSoundStatus').textContent=pulseSoundUrls.call?'Своя мелодия выбрана ✓':'Стандартная мелодия';}
function choosePulseSound(inputId,key){const input=$(inputId);if(!input)return;input.onchange=async()=>{const file=input.files?.[0];input.value='';if(!file)return;if(!file.type.startsWith('audio/')){toast('Выбери аудиофайл');return}if(file.size>10*1024*1024){toast('Размер звука — максимум 10 МБ');return}try{const type=key==='pulseCallSound'?'call':'notification';await storePulseSound(key,file);if(pulseSoundUrls[type])URL.revokeObjectURL(pulseSoundUrls[type]);pulseSoundUrls[type]=URL.createObjectURL(file);updateSoundStatuses();toast('Свой звук сохранён 🔊')}catch(e){toast('Не удалось сохранить звук. Проверь свободное место в браузере.')}}}
function clearPulseSound(key){const type=key==='pulseCallSound'?'call':'notification';if(pulseSoundUrls[type])URL.revokeObjectURL(pulseSoundUrls[type]);delete pulseSoundUrls[type];deletePulseSound(key).catch(()=>{});localStorage.removeItem(key);updateSoundStatuses();toast('Возвращён стандартный звук')}
initPulseSounds();

