async function authenticate(){
 const name=$('nickname').value.trim(),password=$('password').value;
 $('authSubmit').disabled=true;$('loginError').textContent=authMode==='login'?'Входим…':'Создаём аккаунт…';
 try{
  const endpoint=authMode==='login'?'/api/login':'/api/register',body={name,password};
  const r=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Не удалось выполнить запрос');
  myName=data.user.name;try{localStorage.setItem('pulseLastAccount',myName)}catch{}connect();
 }catch(e){$('loginError').textContent=e.message||'Ошибка соединения'}
 finally{$('authSubmit').disabled=false}
}
async function checkSession(){
 try{const r=await fetch('/api/me',{credentials:'same-origin',cache:'no-store'});if(!r.ok)return;const d=await r.json();myName=d.user.name;try{localStorage.setItem('pulseLastAccount',myName)}catch{}connect()}catch{}
}
async function logout(){
 if(!confirm('Выйти из аккаунта на этом устройстве?'))return;
 manualDisconnect=true;clearTimeout(reconnectTimer);try{send({t:'call-end',to:callPeer});if(ws)ws.close();await fetch('/api/logout',{method:'POST'})}catch{}
 if(localStream)localStream.getTracks().forEach(t=>t.stop());location.reload()
}
function connect(){
 if(manualDisconnect)return;
 if(ws&&(ws.readyState===WebSocket.OPEN||ws.readyState===WebSocket.CONNECTING))return;
 $('loginError').textContent='Подключаемся…';if(!myId)$('bootLoader')?.classList.remove('hidden');
 const proto=location.protocol==='https:'?'wss:':'ws:';ws=new WebSocket(proto+'//'+location.host+'/ws');
 ws.onopen=()=>{reconnectDelay=1000;manualDisconnect=false;$('connection').textContent='подключено';send({t:'join',name:myName})};
 ws.onmessage=e=>{let m;try{m=JSON.parse(e.data)}catch{return}handle(m)};
 ws.onerror=()=>{if(!myId){$('loginError').textContent='Не удалось подключиться. Проверь интернет и попробуй снова.';$('bootLoader')?.classList.add('hidden')}};
 ws.onclose=()=>{$('connection').textContent='переподключение…';if(myId&&!manualDisconnect){if(!reconnectNoticeShown){toast('Соединение прервалось — восстанавливаем…');reconnectNoticeShown=true}clearTimeout(reconnectTimer);const delay=reconnectDelay;reconnectDelay=Math.min(15000,Math.round(reconnectDelay*1.8));reconnectTimer=setTimeout(()=>{if(myId&&!manualDisconnect&&(!ws||ws.readyState===WebSocket.CLOSED||ws.readyState===WebSocket.CLOSING)){if(document.visibilityState==='visible'&&navigator.onLine!==false)connect()}},delay)}};
}
function handle(m){
 if(m.t==='messages-deleted'){const ids=new Set(Array.isArray(m.ids)?m.ids:[]);for(const [key,list] of messagesByChat)messagesByChat.set(key,list.filter(item=>!ids.has(item.id)));if(activeId)renderMessages();renderList();return}
 if(m.t==='banned'){clearTimeout(reconnectTimer);if(ws){ws.onclose=null;try{ws.close()}catch{}}myId=null;$('bootLoader')?.classList.add('hidden');$('app').classList.add('hidden');$('login').classList.remove('hidden');$('loginError').textContent=m.reason||'Аккаунт или устройство заблокировано';return}
 if(m.t==='upload-ticket'){const pending=pendingUploadTickets.get(m.requestId);if(pending){pendingUploadTickets.delete(m.requestId);pending.resolve(m.token)}return}
 if(m.t==='auth-required'){ws?.close();$('bootLoader')?.classList.add('hidden');$('login').classList.remove('hidden');$('app').classList.add('hidden');return}
 if(m.t==='welcome'){$('bootLoader')?.classList.add('hidden');myId=m.id;users=m.users||[];unreadCounts=new Map(Object.entries(m.unread||{}));$('login').classList.add('hidden');$('app').classList.remove('hidden');const self=users.find(u=>u.id===myId);$('myName').innerHTML=esc(myName)+adminBadge(self)+giftDecor(self);$('myAvatar').innerHTML=avatarContent(myName,self?.avatar);$('profileBtn').innerHTML=avatarContent(myName,self?.avatar);$('connection').textContent='подключено';(m.history||[]).forEach(x=>pushMessage(globalKey,x,false));try{localStorage.removeItem('pulseActiveChat')}catch{}activeId=null;if(self?.globalChatDisabled){$('welcome').classList.remove('hidden');$('messages').classList.add('hidden');$('composer').classList.add('hidden');$('peerName').textContent='Выбери чат';$('peerStatus').textContent='Доступ к общему чату отключён';renderList();loadCommunity();return}showEmpty();$('app').classList.remove('chat-open');loadCommunity();renderList();void processCallActionFromUrl();return}
 if(m.t==='presence'){users=m.users||[];$('peopleCount').textContent=users.filter(u=>u.id!==myId).length;$('connection').textContent='подключено';const self=users.find(u=>u.id===myId);if(self){myName=self.name||myName;$('myName').innerHTML=esc(myName)+adminBadge(self)+giftDecor(self);$('myAvatar').innerHTML=avatarContent(myName,self.avatar);$('profileBtn').innerHTML=avatarContent(myName,self.avatar)}if(self?.globalChatDisabled&&activeId===globalKey){activeId=globalKey;$('welcome').classList.remove('hidden');$('messages').classList.add('hidden');$('composer').classList.add('hidden');$('peerName').textContent='Выбери чат';$('peerStatus').textContent='Доступ к общему чату отключён'}if(isDM()){const peer=users.find(u=>u.id===activeId);$('peerName').innerHTML=esc(labelFor(activeId))+adminBadge(peer)+giftDecor(peer);$('peerAvatar').innerHTML=avatarContent(labelFor(activeId),peer?.avatar);$('peerStatus').textContent=peer?.online?'В сети':'Не в сети'}renderList();if(isDM())return}
 if(m.t==='reward-notice'){toast((m.title?m.title+' — ':'')+(m.body||'Новое уведомление'));return}if(m.t==='game-state'){for(const list of messagesByChat.values())for(const item of list)if(item.gameInvite?.gameId===m.game?.id)item.gameInvite.game=m.game;renderMessages();return}if(m.t==='pulses-updated'){window.dispatchEvent(new CustomEvent('pulsePulsesUpdated',{detail:m}));return}if(m.t==='gift-inventory-updated'){window.dispatchEvent(new CustomEvent('pulseGiftInventoryUpdated'));return}if(m.t==='presence-refresh'){return}if(m.t==='message'){const msg=m.message,key=msg.channelId?channelKey(msg.channelId):(msg.to?dmKey(msg.from===myId?msg.to:msg.from):globalKey);if(msg.from!==myId&&(document.hidden||key!==currentKey()))playPulseSound('notification');pushMessage(key,msg,false);if(msg.from!==myId){if(key===currentKey()){send({t:'read',ids:[msg.id]});}else unreadCounts.set(key,(unreadCounts.get(key)||0)+1)}renderList();if(key===currentKey())renderMessages();return}
 if(m.t==='message-hidden'){for(const [key,list] of messagesByChat)messagesByChat.set(key,list.filter(x=>x.id!==m.id));renderList();renderMessages();return}if(m.t==='message-delete-result'){toast(m.scope==='everyone'?'Сообщение удалено у всех 🗑':'Сообщение удалено у тебя 🗑');return}
 if(m.t==='message-updated'){for(const list of messagesByChat.values()){const i=list.findIndex(x=>x.id===m.message?.id);if(i>=0)list[i]={...list[i],...m.message}}renderMessages();renderList();return}
 if(m.t==='delivery-receipt'){const peer=m.reader;for(const list of messagesByChat.values())for(const x of list)if(m.ids?.includes(x.id)&&!x.deliveredTo.includes(peer))x.deliveredTo.push(peer);renderMessages();return}
 if(m.t==='read-receipt'){for(const list of messagesByChat.values())for(const x of list)if(m.ids?.includes(x.id)&&!x.readBy.includes(m.reader))x.readBy.push(m.reader);renderMessages();return}
 if(m.t==='typing'){if(m.from===activeId){$('typing').textContent=m.name+' печатает…';$('typing').classList.remove('hidden');clearTimeout(typingTimer);typingTimer=setTimeout(()=>$('typing').classList.add('hidden'),1500)}return}
 if(m.t==='channels'){loadCommunity();renderList();return}if(m.t==='news-post'){newsPosts.unshift(m.post);showNewsAnnouncement(m.post);renderList();return}if(m.t==='news-post-updated'){const i=newsPosts.findIndex(p=>p.id===m.post?.id);if(i>=0)newsPosts[i]=m.post;else newsPosts.unshift(m.post);renderList();return}if(m.t==='error'){toast(m.message||'Ошибка');return}if(m.t==='history'){const key=m.channelId?channelKey(m.channelId):(m.to?dmKey(m.to):globalKey);(m.items||[]).forEach(x=>pushMessage(key,x,false));if(key===currentKey())markCurrentRead();renderMessages();renderList();return}
 if(m.t==='call-offer'){incomingCall(m);return}
 if(m.t==='call-answer'){answerCall(m);return}
 if(m.t==='ice'){if(m.candidate){if(pc&&pc.remoteDescription)pc.addIceCandidate(new RTCIceCandidate(m.candidate)).catch(()=>{});else pendingCandidates.push(m.candidate)}return}
 if(m.t==='call-network-lost'){if(m.from===callPeer&&callPeer)$('callState').textContent='Собеседник переподключается…';return}if(m.t==='call-end'||m.t==='call-reject'){if((m.from===callPeer||!m.from)&&(!m.callId||m.callId===callId))closeCallUI(m.reason||'Звонок завершён');return}
 if(m.t==='call-waiting'){if(m.callId===callId)$('callState').textContent=m.message||'Ожидаем подключения пользователя…';return}
 if(m.t==='call-error'){toast(m.message||'Не удалось позвонить');closeCallUI(m.message);return}
}
async function processCallActionFromUrl(){const url=new URL(location.href),action=url.searchParams.get('callAction'),id=url.searchParams.get('callId');if(!['ring','accept'].includes(action)||!id)return;url.searchParams.delete('callAction');url.searchParams.delete('callId');history.replaceState(null,'',url.pathname+url.search+url.hash);try{const r=await fetch('/api/calls/pending?callId='+encodeURIComponent(id),{credentials:'same-origin',cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Вызов уже недоступен');await incomingCall(d.call);if(action==='accept')setTimeout(()=>{if(callPeer===d.call.from&&!pc)void toggleMute()},180)}catch(e){toast(e.message||'Не удалось открыть вызов')}}
function markCurrentRead(){const list=messagesByChat.get(currentKey())||[],ids=list.filter(m=>m.from!==myId&&!m.readBy?.includes(myId)).map(m=>m.id);if(ids.length)send({t:'read',ids});unreadCounts.set(currentKey(),0)}
function pushMessage(key,msg,rerender=true){const list=messagesByChat.get(key)||[];if(!list.some(x=>x.id===msg.id))list.push(msg);messagesByChat.set(key,list.slice(-300));if(rerender)renderMessages()}
window.pulseInjectMessage=function(msg){if(!msg||!msg.id||!msg.to)return;const key=dmKey(msg.from===myId?msg.to:msg.from);pushMessage(key,msg,false);renderList();if(key===currentKey())renderMessages()};
function renderTabs(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab))}
function renderList(){
 const q=$('search').value.trim().toLowerCase(),el=$('chatList');el.innerHTML='';
 if(tab==='channels'){const list=channels.filter(c=>c.name.toLowerCase().includes(q)||String(c.description).toLowerCase().includes(q));if(!list.length)el.innerHTML='<div class="muted" style="padding:16px">Пока нет каналов. Создай первый через «＋ Канал / группа».</div>';list.forEach(c=>el.append(makeListItem({id:'channel:'+c.id,name:(c.type==='group'?'👥 ':'📣 ')+c.name,subtitle:c.description||(c.type==='group'?'Группа':'Канал')})));return}
 if(tab==='news'){el.innerHTML='<div class="news-create-wrap" style="padding:10px 12px"><button type="button" class="primary" data-open-news-composer style="width:100%;padding:12px;border-radius:12px">✍ Создать новость</button></div>';if(!newsPosts.length)el.insertAdjacentHTML('beforeend','<div class="muted" style="padding:16px">Пока новостей нет.</div>');newsPosts.filter(p=>(p.title+' '+p.body).toLowerCase().includes(q)).forEach(p=>{const n=document.createElement('div');n.className='news-item';const reactions=p.reactions||{},buttons=['❤️','😂','🔥','👍','👏','😮'].map(em=>{const ids=reactions[em]||[];return '<button class="post-reaction '+(ids.includes(myId)?'active':'')+'" data-post-react="'+esc(p.id)+'" data-post-emoji="'+em+'">'+em+' <small>'+ids.length+'</small></button>'}).join('');n.innerHTML='<b>'+esc(p.title)+'</b><p>'+esc(p.body)+'</p><small>'+esc(p.author||'Pulse News')+' · '+new Date(p.at).toLocaleString()+'</small>'+(p.link?'<p><a target="_blank" rel="noopener" href="'+esc(p.link)+'">Открыть ссылку ↗</a></p>':'')+'<div class="post-reactions">'+buttons+'</div>';el.append(n)});return}
 if(tab==='chats'){
  const favs=readFavorites();const self=users.find(u=>u.id===myId),all=[{id:'favorites',name:'⭐ Избранное',subtitle:favs.length?(favs.at(-1).text||favs.at(-1).attachment?.name||'Вложения сохранены'):'Личный чат · только у тебя',group:true},...(self?.globalChatDisabled?[]:[{id:globalKey,name:'Общий чат',subtitle:'Общение со всеми пользователями',group:true},{id:'cookie-bot',name:'🍪 Печенька',subtitle:'Кликай: 30 кликов = 1 Пульс',group:true}])];if(self?.globalChatDisabled)el.innerHTML='<div class="muted" style="padding:16px">🔒 Доступ к общему чату отключён администратором.</div>';
  users.filter(u=>u.id!==myId).forEach(u=>{const has=messagesByChat.has(dmKey(u.id));if(has||u.name.toLowerCase().includes(q))all.push({id:u.id,name:u.name,subtitle:has?lastText(messagesByChat.get(dmKey(u.id)).at(-1)):'Начать переписку'})});
  (window.pulseMiniApps||[]).filter(x=>(x.botName+' '+x.name).toLowerCase().includes(q)).forEach(x=>all.push({id:'mini-bot:'+x.id,name:x.botName,subtitle:'🤖 Бот · '+x.name,group:true}));
  all.filter(x=>x.name.toLowerCase().includes(q)||String(x.subtitle).toLowerCase().includes(q)).forEach(x=>el.append(makeListItem(x)));
 }else{
  const found=users.filter(u=>u.id!==myId&&u.name.toLowerCase().includes(q));if(!found.length)el.innerHTML='<div class="muted" style="padding:16px">Пока никого не найдено. Попроси друга открыть Pulse.</div>';found.forEach(u=>el.append(makeListItem({id:u.id,name:u.name,subtitle:'● '+(u.online?'В сети':'Не в сети')})));
 }
}
