function lastText(m){if(!m)return'Пока нет сообщений';if(m.text)return m.text;const count=(m.attachments||[]).length+(m.attachment?1:0);if(count>1)return '🖼️ Альбом · '+count+' файла';return ((m.attachment?.mime||m.attachments?.[0]?.mime||'').startsWith('image/')?'📷 Фото':((m.attachment?.mime||'').startsWith('video/')?'🎬 Видео':'📎 Файл'))}
function makeListItem(x){const b=document.createElement('div');b.className='chat-item'+(activeId===x.id?' active':'');const key=x.id===globalKey?globalKey:dmKey(x.id),unread=unreadCounts.get(key)||0,onlineClass=x.group?'':(users.some(u=>u.id===x.id&&u.online)?' online':'');const person=users.find(u=>u.id===x.id),shownName=person?labelFor(x.id):x.name,miniBot=String(x.id).startsWith('mini-bot:'),miniApp=miniBot?(window.pulseMiniApps||[]).find(v=>v.id===String(x.id).slice(9)):null,icon=x.id==='cookie-bot'?'🍪':(miniBot?(miniApp?.botImageUrl?'<img class="avatar-image" src="'+esc(miniApp.botImageUrl)+'" alt="">':esc(miniApp?.botIcon||'🤖')):(x.group?'✦':avatarContent(shownName,person?.avatar)));b.innerHTML='<div class="avatar">'+icon+'</div><div class="chat-preview"><div class="chat-meta"><b>'+esc(shownName)+adminBadge(person)+giftDecor(person)+'</b><span class="presence-badge'+onlineClass+'"></span></div><small>'+esc(x.subtitle)+'</small></div>'+(unread?'<span class="unread-badge">'+(unread>99?'99+':unread)+'</span>':'');b.onclick=()=>openChat(x.id);return b}
