function closeMediaViewer(){const el=$('mediaViewer');if(!el)return;const v=el.querySelector('video');if(v){try{v.pause();v.removeAttribute('src');v.load()}catch{}}el.remove();document.body.classList.remove('media-viewer-open')}
function openMediaViewer(url,type,name){if(!url)return;closeMediaViewer();const el=document.createElement('div');el.id='mediaViewer';el.className='media-viewer';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-label','Просмотр медиа');const isVideo=(type||'').startsWith('video/');el.innerHTML='<button type="button" class="media-viewer-close" aria-label="Закрыть просмотр" title="Закрыть (Esc)">×</button><div class="media-viewer-stage">'+(isVideo?'<video controls autoplay playsinline src="'+esc(url)+'"></video>':'<img src="'+esc(url)+'" alt="'+esc(name||'Фото')+'">')+'</div>';el.addEventListener('click',e=>{if(e.target===el||e.target.classList.contains('media-viewer-stage'))closeMediaViewer()});el.querySelector('.media-viewer-close').addEventListener('click',closeMediaViewer);document.body.appendChild(el);document.body.classList.add('media-viewer-open');el.querySelector('.media-viewer-close').focus()}
function attachmentHTML(a){if(!a)return'';const url=esc(a.url),name=esc(a.name),type=a.mime||'',isImage=type.startsWith('image/'),isVideo=type.startsWith('video/'),isAudio=type.startsWith('audio/');if(isImage)return '<button type="button" class="media-open" data-media-url="'+url+'" data-media-type="'+esc(type)+'" data-media-name="'+name+'" aria-label="Открыть фото"><img class="attachment" loading="lazy" src="'+url+'" alt="'+name+'"></button>';if(isVideo)return '<button type="button" class="media-open media-open-video" data-media-url="'+url+'" data-media-type="'+esc(type)+'" data-media-name="'+name+'" aria-label="Открыть видео"><span>▶</span><video class="attachment" preload="metadata" muted playsinline src="'+url+'"></video></button>';if(isAudio)return '<audio class="attachment" controls src="'+url+'"></audio>';return '<a class="file-card" href="'+url+'" target="_blank" rel="noopener" download="'+name+'"><span>📎</span><div>'+name+'<small>'+Math.max(1,Math.round((a.size||0)/1024))+' KB</small></div></a>'}
function attachmentsHTML(m){const seen=new Set(),items=[...(Array.isArray(m.attachments)?m.attachments:[]),...(m.attachment?[m.attachment]:[])].filter(a=>{if(!a)return false;const name=String(a.name||'').trim().toLowerCase(),size=String(a.size||0),mime=String(a.mime||'').toLowerCase();const key=name?name+'|'+size+'|'+mime:String(a.url||'');if(seen.has(key))return false;seen.add(key);return true});if(!items.length)return '';if(items.length===1)return attachmentHTML(items[0]);if(items.every(a=>(a.mime||'').startsWith('image/'))){return '<div class="media-album album-count-'+Math.min(4,items.length)+'">'+items.map(a=>'<button type="button" class="media-open" data-media-url="'+esc(a.url)+'" data-media-type="'+esc(a.mime||'image/*')+'" data-media-name="'+esc(a.name||'Фото')+'" title="'+esc(a.name||'Фото')+'" aria-label="Открыть фото"><img class="attachment" loading="lazy" src="'+esc(a.url)+'" alt="'+esc(a.name||'Фото')+'"></button>').join('')+'</div>'}return '<div class="attachment-stack">'+items.map(attachmentHTML).join('')+'</div>'}
function ensureReplyPreview(){let el=$('replyPreview');if(!el){el=document.createElement('div');el.id='replyPreview';el.className='reply-preview hidden';const row=document.querySelector('.compose-row');if(row)row.parentNode.insertBefore(el,row)}return el}
function setReply(m){replyingTo=m||null;const el=ensureReplyPreview();if(!m){el.classList.add('hidden');el.innerHTML='';return}el.classList.remove('hidden');el.innerHTML='<div class="reply-preview-copy"><b>↩ Ответ на '+esc(m.name||'сообщение')+'</b><span>'+esc(m.deletedForEveryone?'Сообщение удалено':(m.text||m.attachment?.name||'Вложение'))+'</span></div><button type="button" class="reply-cancel" title="Отменить ответ">×</button>';el.querySelector('.reply-cancel').onclick=()=>setReply(null)}

const STICKER_PREFIX='PULSE_STICKER:';
const defaultStickerPack={id:'pulse-arena',name:'Pulse Arena',stickers:[{emoji:'🏆',label:'GG!'},{emoji:'✨',label:'NICE!'},{emoji:'🔥',label:'CLUTCH'},{emoji:'👑',label:'MVP'},{emoji:'😂',label:'Ахаха'},{emoji:'💀',label:'BRUH'},{emoji:'🚀',label:'Погнали!'},{emoji:'😎',label:'ЛЕГЕНДА'},{emoji:'🫡',label:'Принято'},{emoji:'💜',label:'Pulse'},{emoji:'😴',label:'AFK'},{emoji:'🎉',label:'ПОБЕДА'}]};
let stickerDraft=[],sharedStickerPacks=[],adminAvatarData='';
function getStickerPacks(){let local=[];try{const x=JSON.parse(localStorage.getItem('pulseStickerPacks')||'[]');local=Array.isArray(x)?x.filter(p=>p&&p.id&&Array.isArray(p.stickers)):[]}catch{}const ids=new Set();return [defaultStickerPack,...sharedStickerPacks,...local].filter(p=>{if(ids.has(p.id))return false;ids.add(p.id);return true})}
async function loadSharedStickerPacks(){try{const r=await fetch('/api/sticker-packs',{credentials:'same-origin'}),d=await r.json();if(r.ok)sharedStickerPacks=Array.isArray(d.packs)?d.packs:[]}catch{}}
async function uploadStickerImage(file){if(!file)return '';const byExt={webp:'image/webp',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif'},extMatch=String(file.name||'').match(/\.(webp|png|jpe?g|gif)$/i),ext=extMatch?extMatch[1].toLowerCase():'',byMime={'image/webp':'webp','image/png':'png','image/jpeg':'jpg','image/gif':'gif'},mimeType=/^image\/(png|jpeg|webp|gif)$/i.test(file.type)?file.type.toLowerCase():byExt[ext];if(!mimeType||file.size>5*1024*1024)throw new Error('Картинка должна быть PNG/JPG/WEBP/GIF до 5 МБ. Тип: '+(file.type||'не определён'));const finalExt=ext||byMime[mimeType],safeName=(String(file.name||'').trim()&&/\.(webp|png|jpe?g|gif)$/i.test(file.name))?file.name:'sticker.'+finalExt;const r=await fetch('/upload?name='+encodeURIComponent(safeName),{method:'POST',headers:{'content-type':mimeType},body:file,credentials:'same-origin'});let d;try{d=await r.json()}catch{throw new Error('Сервер вернул некорректный ответ при загрузке стикера')}if(!r.ok)throw new Error(d.error||'Не удалось загрузить картинку');if(!/\/uploads\/[a-f0-9]{32}\.(png|jpe?g|webp|gif)$/i.test(d.url||''))throw new Error('Сервер сохранил стикер без расширения изображения. Повтори загрузку.');return d.url}
function stickerMessageHTML(m,quote,forwarded){const text=String(m.text||'');if(m.deletedForEveryone)return '<div class="deleted-text">Это сообщение удалено</div>';if(m.kind==='call-summary'&&m.callSummary){const c=m.callSummary,d=Number(c.duration)||0,mins=Math.floor(d/60),secs=d%60;return quote+forwarded+'<div class="call-summary-card"><span class="call-summary-icon">'+(c.type==='video'?'📹':'☎️')+'</span><div><b>'+(c.type==='video'?'Видеозвонок':'Голосовой звонок')+'</b><small>Звонок завершён · '+(mins?mins+' мин ':'')+secs+' сек</small></div></div>'}if(m.kind==='gift'&&m.giftPurchase){const g=m.giftPurchase;return quote+forwarded+'<div class="gift-purchase-card"><div class="gift-purchase-art"><span class="gift-purchase-emoji">'+esc(g.emoji||'🎁')+'</span><div><strong>'+esc(g.buyerName||m.name)+' подарил(а) '+esc(g.recipientName||'пользователю')+'</strong><small>'+esc(g.name)+' · '+esc(g.rarity||'Подарок')+'</small></div></div><div class="gift-purchase-ribbon">Подарок · '+Number(g.price||0).toLocaleString('ru-RU')+' ⚡</div></div>'}if(m.kind==='action-invite'&&m.actionInvite){const a=m.actionInvite,pending=a.status==='pending';return quote+forwarded+'<div class="action-invite-card"><b>💌 '+esc(a.fromName)+' предлагает: '+esc(a.action)+'</b>'+(pending&&m.to===myId?'<div class="invite-actions"><button type="button" class="primary" data-invite-response="'+esc(m.id)+'" data-invite-accept="true">Принять</button><button type="button" class="secondary" data-invite-response="'+esc(m.id)+'" data-invite-accept="false">Отклонить</button></div>': '<small>'+esc(m.text||(a.status==='accepted'?'Приглашение принято ✓':a.status==='rejected'?'Приглашение отклонено':'Ожидает ответа'))+'</small>')+'</div>'}if(m.kind==='game-invite'&&m.gameInvite){const g=m.gameInvite,game=g.game,pending=g.status==='pending';let board='';if(game){board='<div class="ttt-board">'+game.board.map((v,i)=>'<button type="button" data-game-move="'+esc(game.id)+'" data-game-index="'+i+'" '+(game.status!=='playing'||game.turn!==myId||v?'disabled':'')+'>'+esc(v||'')+'</button>').join('')+'</div><small>'+(game.status==='playing'?(game.turn===myId?'Твой ход ('+(game.players[0]===myId?'X':'O')+')':'Ход '+esc(game.names[game.turn]||'соперника')):esc(game.resultText||'Игра завершена'))+'</small>'}return quote+forwarded+'<div class="game-invite-card"><b>🎮 Крестики-нолики</b><p>'+esc(g.fromName)+' вызывает '+esc(g.toName)+' на дуэль без ставок</p>'+(pending&&m.to===myId?'<div class="invite-actions"><button type="button" class="primary" data-invite-response="'+esc(m.id)+'" data-invite-accept="true">Принять дуэль</button><button type="button" class="secondary" data-invite-response="'+esc(m.id)+'" data-invite-accept="false">Отклонить</button></div>':!pending&&!game?'<small>'+esc(g.status==='accepted'?'Дуэль принята':'Дуэль отклонена')+'</small>':'')+board+'</div>'}if(m.kind==='poll'&&m.poll){const p=m.poll,opts=p.options||[],total=opts.reduce((n,o)=>n+(o.votes||[]).length,0),voted=opts.some(o=>(o.votes||[]).includes(myId));return quote+forwarded+'<div class="poll-card"><h4>📊 '+esc(p.question)+'</h4>'+opts.map(o=>{const count=(o.votes||[]).length,percent=total?Math.round(count*100/total):0;return '<button class="poll-option '+((o.votes||[]).includes(myId)?'voted':'')+'" data-poll-vote="'+esc(m.id)+'" data-poll-option="'+esc(o.id)+'" '+(voted?'disabled':'')+'><span>'+esc(o.text)+'</span><small>'+count+' · '+percent+'%</small></button>'}).join('')+'<div class="poll-total">'+total+' голосов'+(voted?' · ты проголосовал':'')+'</div></div>'}if(m.kind==='background-invite'&&m.background){const bg=m.background.value||'violet',preset=chatBackgrounds()[bg],mine=m.from===myId;return quote+forwarded+'<div class="background-invite-card"><b>🎨 '+esc(m.name||'Собеседник')+' предлагает новый фон</b><small>'+esc(preset?.name||m.background.name||'Фон чата')+'</small><span class="background-invite-swatch" style="background:'+esc(preset?.css||'linear-gradient(135deg,#8b70ff,#56e5e8)')+'"></span>'+(mine?'<small>Собеседнику отправлено предложение</small>':'<button type="button" class="primary" data-background-accept="'+esc(bg)+'">Включить такой же фон</button>')+'</div>'}if(text.startsWith(STICKER_PREFIX)){try{const s=JSON.parse(text.slice(STICKER_PREFIX.length)),image=String(s.image||'');const art=image&&/^\/uploads\/[a-f0-9]{32}\.(png|jpe?g|webp|gif)$/i.test(image)?'<img class="sticker-image" loading="lazy" alt="Стикер" src="'+esc(image)+'">':'<span>'+esc(String(s.emoji||'✨').slice(0,12))+'</span>';return quote+forwarded+'<div class="pulse-sticker-message">'+art+(s.label?'<small>'+esc(String(s.label).slice(0,80))+'</small>':'')+'</div>'+attachmentHTML(m.attachment)}catch{}}return quote+forwarded+'<div class="bubble">'+(m.text?formatText(m.text):'')+'</div>'}
async function openStickerPicker(){if(!activeId){toast('Сначала открой чат');return}await loadSharedStickerPacks();renderStickerPicker();showModal('stickerModal')}
function renderStickerPicker(){const packs=getStickerPacks(),select=$('stickerPackSelect'),chosen=select.value||packs[0].id;select.innerHTML=packs.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+(p.creator?' · '+esc(p.creator):'')+'</option>').join('');select.value=packs.some(p=>p.id===chosen)?chosen:packs[0].id;const pack=packs.find(p=>p.id===select.value)||packs[0];$('stickerGrid').innerHTML=pack.stickers.map((s,i)=>'<button type="button" class="sticker-tile" data-send-sticker="'+esc(pack.id)+'" data-sticker-index="'+i+'">'+(s.image?'<img class="sticker-thumb" loading="lazy" alt="Стикер" src="'+esc(s.image)+'">':'<span>'+esc(s.emoji||'✨')+'</span>')+'<small>'+esc(s.label||'')+'</small></button>').join('')||'<p class="muted">В наборе пока нет стикеров.</p>'}
function sendSticker(packId,index){const pack=getStickerPacks().find(p=>p.id===packId),sticker=pack?.stickers?.[Number(index)];if(!sticker)return;send({t:'message',text:STICKER_PREFIX+JSON.stringify({emoji:String(sticker.emoji||'✨').slice(0,12),label:String(sticker.label||'').slice(0,80),image:String(sticker.image||'')}),to:isDM()?activeId:null,channelId:isChannel()?activeChannelId():null});hideModal('stickerModal')}
function openStickerCreator(){stickerDraft=[];$('stickerPackName').value='';$('stickerEmojiInput').value='✨';$('stickerLabelInput').value='';$('stickerImageInput').value='';$('stickerCreator').classList.remove('hidden');renderStickerDraft()}
function renderStickerDraft(){$('stickerDraftGrid').innerHTML=stickerDraft.map((s,i)=>'<button type="button" class="sticker-draft-item" data-remove-draft="'+i+'">'+(s.image?'<img src="'+esc(s.image)+'" alt="">':'<span>'+esc(s.emoji)+'</span>')+'<small>'+esc(s.label)+'</small><i>×</i></button>').join('')||'<small class="muted">Добавь стикер — эмодзи или картинку PNG/JPG/WEBP/GIF.</small>'}
async function addStickerDraft(){const emoji=$('stickerEmojiInput').value.trim(),label=$('stickerLabelInput').value.trim(),file=$('stickerImageInput').files?.[0];if(!emoji&&!file){toast('Добавь эмодзи или выбери картинку');return}if(stickerDraft.length>=40){toast('В одном наборе максимум 40 стикеров');return}const btn=$('addStickerDraft');btn.disabled=true;try{const image=file?await uploadStickerImage(file):'';stickerDraft.push({emoji:emoji.slice(0,12),label:label.slice(0,80),image});$('stickerLabelInput').value='';$('stickerImageInput').value='';renderStickerDraft();toast('Стикер добавлен в набор')}catch(e){toast(e.message||'Не удалось добавить картинку')}finally{btn.disabled=false}}

async function unzipStickerImages(file){
 const buf=await file.arrayBuffer(),view=new DataView(buf),bytes=new Uint8Array(buf);let eocd=-1;
 for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65558);i--){if(view.getUint32(i,true)===0x06054b50){eocd=i;break}}
 if(eocd<0)throw new Error('Не вижу ZIP-структуру. Попробуй другой архив.');
 const count=view.getUint16(eocd+10,true),centralOffset=view.getUint32(eocd+16,true);let p=centralOffset,items=[];
 for(let i=0;i<count&&p+46<=bytes.length;i++){
  if(view.getUint32(p,true)!==0x02014b50)break;
  const method=view.getUint16(p+10,true),compressed=view.getUint32(p+20,true),uncompressed=view.getUint32(p+24,true),nameLen=view.getUint16(p+28,true),extraLen=view.getUint16(p+30,true),commentLen=view.getUint16(p+32,true),local=view.getUint32(p+42,true);
  const name=new TextDecoder().decode(bytes.slice(p+46,p+46+nameLen));p+=46+nameLen+extraLen+commentLen;
  if(name.endsWith('/')||name.includes('__MACOSX/')||name.split('/').pop().startsWith('.'))continue;
  const ext=(name.match(/\.[^.]+$/)||[''])[0].toLowerCase();if(!['.webp','.png','.jpg','.jpeg','.gif'].includes(ext))continue;
  if(items.length>=40)break;if(uncompressed>5*1024*1024)continue;
  if(local+30>bytes.length||view.getUint32(local,true)!==0x04034b50)continue;
  const start=local+30+view.getUint16(local+26,true)+view.getUint16(local+28,true),end=start+compressed;if(end>bytes.length)continue;
  let raw=bytes.slice(start,end);
  if(method===8){if(typeof DecompressionStream==='undefined')throw new Error('Этот браузер не умеет распаковывать ZIP. Распакуй архив и выбери изображения.');raw=new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer())}
  else if(method!==0)continue;
  if(raw.length>5*1024*1024)continue;
  const type={'.webp':'image/webp','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.gif':'image/gif'}[ext];
  items.push(new File([raw],name.split('/').pop(),{type}));
 }
 return items
}
async function importStickerFiles(files){
 const valid=files.filter(f=>/\.(zip|wastickers)$/i.test(f.name)||/^image\/(png|jpeg|webp|gif)$/.test(f.type)||/\.(webp|png|jpe?g|gif)$/i.test(f.name));
 if(!valid.length){toast('Выбери ZIP/.wastickers или изображения PNG/JPG/WEBP/GIF');return}
 const importBtn=$('importStickerFiles');importBtn.disabled=true;$('stickerCreator').classList.remove('hidden');
 try{
  let added=0,failed=0;
  for(const f of valid){
   if(stickerDraft.length>=40)break;
   if(/\.(zip|wastickers)$/i.test(f.name)){
    if(f.size>25*1024*1024)throw new Error('Архив должен быть меньше 25 МБ');
    $('stickerImportStatus').textContent='Распаковываем '+f.name+' на сервере…';
    const r=await fetch('/api/import-sticker-archive',{method:'POST',headers:{'content-type':'application/octet-stream'},credentials:'same-origin',body:f});
    const d=await r.json();if(!r.ok)throw new Error(d.error||'Сервер не смог распаковать архив');
    if(!$('stickerPackName').value.trim())$('stickerPackName').value=f.name.replace(/\.(zip|wastickers)$/i,'').slice(0,40)||'Импортированный набор';
    for(const item of d.stickers||[]){if(stickerDraft.length>=40)break;stickerDraft.push(item);added++}
    renderStickerDraft();
   }else{
    if(!/^image\/(png|jpeg|webp|gif)$/.test(f.type)&&! /\.(webp|png|jpe?g|gif)$/i.test(f.name))continue;
    if(f.size>5*1024*1024)continue;
    $('stickerImportStatus').textContent='Загружаем '+f.name+'…';
    try{const image=await uploadStickerImage(f);stickerDraft.push({emoji:'✨',label:f.name.replace(/\.[^.]+$/,'').slice(0,80),image});added++;renderStickerDraft();if(!$('stickerPackName').value.trim())$('stickerPackName').value='Импортированный набор'}
    catch(uploadError){console.warn('Pulse sticker skipped:',f.name,uploadError);failed++;$('stickerImportStatus').textContent='Пропущен '+f.name+' — '+(uploadError.message||'ошибка загрузки')+'; продолжаем…';}
   }
  }
  if(!added)throw new Error('Не удалось найти подходящие стикеры в выбранном файле');
  $('stickerImportStatus').textContent='Готово: добавлено '+added+' стикеров'+(failed?' · пропущено '+failed:'')+'. Теперь нажми «Сохранить набор». ';
  toast('Импортировано стикеров: '+added+' ✨');
 }catch(e){$('stickerImportStatus').textContent='Ошибка: '+(e.message||'не удалось импортировать');toast(e.message||'Не удалось импортировать набор')}
 finally{importBtn.disabled=false}
}
