async function handleMessageAction(action,id){const list=messagesByChat.get(currentKey())||[],m=list.find(x=>x.id===id);if(!m)return;if(action==='reply'){setReply(m);$('messageInput').focus();return}if(action==='edit'){if(m.from!==myId||m.deletedForEveryone)return;const value=prompt('Изменить сообщение:',m.text||'');if(value===null)return;if(!value.trim()&&!m.attachment){toast('Сообщение не может быть пустым');return}send({t:'edit-message',id:m.id,text:value});return}if(action==='copy'){const text=m.deletedForEveryone?'':(m.text||m.attachment?.name||'');try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();document.execCommand('copy');t.remove()}toast('Скопировано ✓')}catch{toast('Не удалось скопировать')}return}if(action==='forward'){const nick=prompt('Кому переслать? Введи точный ник пользователя:');if(!nick)return;const target=users.find(u=>u.name.toLowerCase()===nick.trim().toLowerCase()&&u.id!==myId);if(!target){toast('Пользователь не найден');return}if(m.deletedForEveryone||(!m.text&&!m.attachment)){toast('Это сообщение нельзя переслать');return}send({t:'message',text:m.text||'',to:target.id,attachment:m.attachment||null,forwardedFrom:m.id});toast('Сообщение переслано ➦');return}if(action==='delete-self'||action==='delete-all'){const all=action==='delete-all';if(!confirm(all?'Удалить это сообщение и вложение у всех?':'Убрать это сообщение только у себя?'))return;try{await waitForSocket();send({t:'delete-message',id:m.id,scope:all?'everyone':'self',requestId:crypto.randomUUID()})}catch(e){toast(e.message||'Не удалось удалить сообщение')}}}
function submitMessage(){const input=$('messageInput'),text=input.value.trim();if(!text)return;if(activeId==='favorites'){pushFavorite({id:crypto.randomUUID(),from:myId,name:myName,text,at:Date.now(),readBy:[],deliveredTo:[]});input.value='';input.style.height='auto';setReply(null);input.focus();return}send({t:'message',text,to:isDM()?activeId:null,channelId:isChannel()?activeChannelId():null,replyTo:replyingTo?.id||null});input.value='';input.style.height='auto';setReply(null);input.focus()}

async function waitForSocket(timeout=10000){const started=Date.now();while(Date.now()-started<timeout){if(ws&&ws.readyState===1)return;await new Promise(resolve=>setTimeout(resolve,200))}throw new Error('Нет соединения с чатом. Подожди пару секунд и повтори отправку')}async function getUploadTicket(){if(!ws||ws.readyState!==1)await waitForSocket();const requestId=crypto.randomUUID();return await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pendingUploadTickets.delete(requestId);reject(new Error('Не удалось подтвердить сессию. Повтори попытку'))},8000);pendingUploadTickets.set(requestId,{resolve:token=>{clearTimeout(timer);resolve(token)},reject:error=>{clearTimeout(timer);reject(error)}});send({t:'upload-ticket',requestId})})}
function setUploadProgress(percent,label){const wrap=$('uploadProgress'),fill=$('uploadProgressFill'),value=Math.max(0,Math.min(100,Math.round(Number(percent)||0)));if(wrap){wrap.classList.remove('hidden');wrap.setAttribute('aria-valuenow',String(value));wrap.setAttribute('aria-label','Загрузка файлов: '+value+'%')}if(fill){fill.style.width=value+'%';fill.textContent=value+'%';fill.setAttribute('aria-hidden','true')}if($('uploadStatus'))$('uploadStatus').textContent=(label?label+' · ':'')+value+'%'}
function uploadBinaryWithProgress(file,token,onProgress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/upload?name='+encodeURIComponent(file.name||'file'));xhr.withCredentials=true;xhr.timeout=180000;xhr.setRequestHeader('content-type',file.type||'application/octet-stream');xhr.setRequestHeader('authorization','Bearer '+token);xhr.upload.onprogress=e=>{if(e.lengthComputable){const pct=Math.round(e.loaded/e.total*100);if(onProgress)onProgress(pct);else setUploadProgress(pct,'Загрузка '+(file.name||'файла'))}};xhr.onload=()=>{let data;try{data=JSON.parse(xhr.responseText||'{}')}catch{reject(new Error('Сервер вернул некорректный ответ'));return}if(xhr.status<200||xhr.status>=300){const error=new Error(data.error||'Ошибка загрузки · HTTP '+xhr.status);error.status=xhr.status;reject(error);return}resolve(data)};xhr.onerror=()=>reject(new Error('Сетевая ошибка. Проверь интернет и повтори отправку'));xhr.ontimeout=()=>reject(new Error('Загрузка заняла слишком много времени. Попробуй ещё раз'));xhr.onabort=()=>reject(new Error('Загрузка отменена'));setUploadProgress(0,'Подготовка загрузки · '+(file.name||'файл'));xhr.send(file)})}
function uploadLargeFileToGofile(file,onProgress){
 return new Promise((resolve,reject)=>{
  const form=new FormData();form.append('file',file,file.name||'file');
  const xhr=new XMLHttpRequest();xhr.open('POST','https://upload.gofile.io/uploadfile');xhr.timeout=0;
  xhr.upload.onprogress=e=>{if(e.lengthComputable&&onProgress)onProgress(Math.round(e.loaded/e.total*100))};
  xhr.onload=()=>{let data;try{data=JSON.parse(xhr.responseText||'{}')}catch{reject(new Error('Внешнее хранилище вернуло некорректный ответ'));return}
   if(xhr.status<200||xhr.status>=300||data.status!=='ok'||!data.data?.downloadPage){reject(new Error(data.data?.message||data.message||'Внешнее хранилище не приняло файл. Попробуй позже'));return}
   resolve({url:data.data.downloadPage,name:file.name||data.data.name||'file',size:file.size,mime:file.type||data.data.mimetype||'application/octet-stream',external:true})
  };
  xhr.onerror=()=>reject(new Error('Сетевая ошибка при загрузке во внешнее хранилище'));
  xhr.onabort=()=>reject(new Error('Загрузка во внешнее хранилище отменена'));
  setUploadProgress(0,'Внешнее хранилище · '+(file.name||'файл'));xhr.send(form)
 })
}
async function uploadOneFile(file,index,total){
 const maxBytes=100*1024*1024;
 if(file.size>maxBytes)return await uploadLargeFileToGofile(file,pct=>setUploadProgress(pct,'Внешнее хранилище · '+file.name));
 let a;
 for(let attempt=0;attempt<2;attempt++){
  const uploadToken=await getUploadTicket();
  try{a=await uploadBinaryWithProgress(file,uploadToken,pct=>setUploadProgress(pct,'Файл '+(index+1)+' из '+total+' · '+file.name));break}
  catch(e){if(e.status===401&&attempt===0){setUploadProgress(0,'Обновляем сессию загрузки…');continue}throw e}
 }
 if(!a)throw new Error('Не удалось получить файл от сервера');
 return {...a,mime:file.type||a.mime};
}
async function uploadFile(fileList){
 if(uploadInProgress)return;
 const seen=new Set(),files=[...(fileList||[])].filter(file=>{const key=[file.name,file.size,file.lastModified,file.type].join('|');if(seen.has(key))return false;seen.add(key);return true});
 if(!files.length)return;
 if(files.length>20){toast('За один раз можно отправить максимум 20 файлов');return}
 uploadInProgress=true;
 $('attach').disabled=true;$('fileInput').disabled=true;
 let sent=0,failed=[];
 try{
  const uploaded=[];
  for(let i=0;i<files.length;i++){
   const file=files[i];
   try{setUploadProgress(Math.round(i/files.length*100),'Файл '+(i+1)+' из '+files.length+' · '+file.name);uploaded.push({file,attachment:await uploadOneFile(file,i,files.length)})}
   catch(e){failed.push(file.name+': '+(e.message||'ошибка'));toast('Не удалось загрузить '+file.name+': '+(e.message||'ошибка'))}
  }
  if(activeId==='favorites'){
   const images=uploaded.filter(x=>(x.file.type||'').startsWith('image/'));
   const other=uploaded.filter(x=>!(x.file.type||'').startsWith('image/'));
   if(images.length)pushFavorite({id:crypto.randomUUID(),from:myId,name:myName,text:'',attachments:images.map(x=>x.attachment),at:Date.now(),readBy:[],deliveredTo:[]});
   for(const x of other)pushFavorite({id:crypto.randomUUID(),from:myId,name:myName,text:'',attachment:x.attachment,at:Date.now(),readBy:[],deliveredTo:[]});
   sent=uploaded.length;
  }else{
   const images=uploaded.filter(x=>(x.file.type||'').startsWith('image/'));
   const other=uploaded.filter(x=>!(x.file.type||'').startsWith('image/'));
   if(images.length){send({t:'message',text:'',to:isDM()?activeId:null,channelId:isChannel()?activeChannelId():null,replyTo:replyingTo?.id||null,attachments:images.map(x=>x.attachment)});sent+=images.length}
   for(const x of other){send({t:'message',text:'',to:isDM()?activeId:null,channelId:isChannel()?activeChannelId():null,replyTo:replyingTo?.id||null,attachment:x.attachment});sent++}
   if(!ws||ws.readyState!==1)throw new Error('Соединение чата потеряно');
  }
  setUploadProgress(100,'Готово: '+sent+' из '+files.length+' файлов отправлено');
  if(sent===files.length)toast(imagesCount(uploaded)+'');else toast('Отправлено '+sent+' из '+files.length+'. Не удалось: '+failed.length);
  setReply(null);
 }finally{
  uploadInProgress=false;
  $('attach').disabled=false;$('fileInput').disabled=false;
  setTimeout(()=>{if($('uploadProgress'))$('uploadProgress').classList.add('hidden');if($('uploadProgressFill'))$('uploadProgressFill').style.width='0%';if($('uploadStatus'))$('uploadStatus').textContent=''},6000)
 }
}
function imagesCount(uploaded){const n=uploaded.filter(x=>(x.file.type||'').startsWith('image/')).length;return n>1?'Отправлен альбом из '+n+' фото ✓':'Файлы отправлены ✓'}
async function toggleCircleRecord(){
 if(mediaRecorder&&mediaRecorder.state==='recording'&&mediaRecorder.__pulseCircle){mediaRecorder.stop();$('circleRecord').textContent='🔴';$('circleRecord').style.color='';return}
 if(mediaRecorder&&mediaRecorder.state==='recording'){toast('Сначала заверши запись голосового сообщения');return}
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Запись видео не поддерживается этим браузером');return}
 if(!activeId||activeId==='cookie-bot'){toast('Сначала открой чат');return}
 let stream;
 try{
  stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:720},height:{ideal:720}},audio:true});
  const mime=['video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t))||'';
  recordChunks=[];
  const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);
  recorder.__pulseCircle=true;mediaRecorder=recorder;
  recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};
  recorder.onerror=()=>{stream.getTracks().forEach(t=>t.stop());toast('Не удалось записать видеокружок')};
  recorder.onstop=async()=>{
   stream.getTracks().forEach(t=>t.stop());$('circleRecord').textContent='🔴';$('circleRecord').style.color='';
   const type=recorder.mimeType||'video/webm',blob=new Blob(recordChunks,{type});
   if(!blob.size){toast('Видео пустое — попробуй ещё раз');return}
   const ext=type.includes('mp4')?'.mp4':'.webm',file=new File([blob],'circle-'+Date.now()+ext,{type});
   if(uploadInProgress){toast('Дождись завершения другой загрузки');return}
   uploadInProgress=true;$('attach').disabled=true;$('fileInput').disabled=true;
   try{setUploadProgress(1,'Загружаем видеокружок…');const attachment=await uploadOneFile(file,0,1);send({t:'message',text:'',to:isDM()?activeId:null,channelId:isChannel()?activeChannelId():null,replyTo:replyingTo?.id||null,kind:'circle-video',circleShape:localStorage.getItem('pulseCircleShape')||'circle',attachment});setReply(null);toast('Видеокружок отправлен 🎥')}
   catch(e){toast('Не удалось отправить кружок: '+(e.message||'ошибка'))}
   finally{uploadInProgress=false;$('attach').disabled=false;$('fileInput').disabled=false}
  };
  recorder.start();$('circleRecord').textContent='■';$('circleRecord').style.color='#ff6685';toast('Запись кружка идёт · нажми ■, чтобы отправить');
 }catch(e){if(stream)stream.getTracks().forEach(t=>t.stop());toast('Разреши доступ к камере и микрофону')}
}
async function toggleRecord(){if(mediaRecorder&&mediaRecorder.state==='recording'){mediaRecorder.stop();$('record').textContent='🎙';$('record').style.color='';return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Запись голоса не поддерживается этим браузером');return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});recordChunks=[];mediaRecorder=new MediaRecorder(stream);mediaRecorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};mediaRecorder.onstop=async()=>{const blob=new Blob(recordChunks,{type:mediaRecorder.mimeType||'audio/webm'}),ext=blob.type.includes('ogg')?'.ogg':blob.type.includes('mp4')?'.mp4':'.webm',file=new File([blob],'voice-message'+ext,{type:blob.type});stream.getTracks().forEach(t=>t.stop());await uploadFile(file)};mediaRecorder.start();$('record').textContent='■';$('record').style.color='#ff6685';toast('Запись идёт — нажми ■, чтобы отправить')}catch(e){toast('Разреши доступ к микрофону в браузере')}} 
async function startCall(type){if(!isDM()){toast('Для звонка выбери человека во вкладке «Люди»');return}const target=users.find(u=>u.id===activeId);if(!target){toast('Этот человек сейчас не в сети');return}callPeer=target.id;callType=type;callId=(crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random().toString(16).slice(2));callStartedAt=0;callInitiator=true;micMuted=false;cameraOff=false;$('callName').textContent=target.name;$('callAvatar').textContent=avatar(target.name);$('callState').textContent='Запрашиваем доступ к '+(type==='video'?'камере и микрофону':'микрофону')+'…';$('callOverlay').classList.remove('hidden');try{localStream=await navigator.mediaDevices.getUserMedia({audio:true,video:type==='video'});$('localVideo').srcObject=localStream;$('localVideo').classList.toggle('hidden',type!=='video');pc=createPeer();for(const track of localStream.getTracks())pc.addTrack(track,localStream);const offer=await pc.createOffer();await pc.setLocalDescription(offer);send({t:'call-offer',to:callPeer,offer:offer,type,callId});$('callState').textContent='Звоним…'}catch(e){toast('Не удалось начать звонок: '+e.message);closeCallUI('Не удалось начать звонок')}}
function createPeer(){const peer=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'}]});peer.onicecandidate=e=>{if(e.candidate)send({t:'ice',to:callPeer,candidate:e.candidate})};peer.ontrack=e=>{const stream=e.streams[0];$('remoteVideo').srcObject=stream;$('remoteVideoWrap').classList.remove('hidden');$('callState').textContent='Соединение установлено'};peer.onconnectionstatechange=()=>{if(peer.connectionState==='connected'){$('callState').textContent='На связи';if(!callStartedAt)callStartedAt=Date.now()}if(['failed','disconnected'].includes(peer.connectionState))$('callState').textContent='Связь нестабильна'};return peer}
async function incomingCall(m){if(callPeer){send({t:'call-reject',to:m.from,callId:m.callId,reason:'busy'});return}callPeer=m.from;callType=m.type||'audio';callId=m.callId||null;callStartedAt=0;callInitiator=false;window.incomingOffer=m.offer;$('callName').textContent=m.fromName||'Входящий звонок';$('callAvatar').textContent=avatar(m.fromName);$('callState').textContent='Входящий '+(callType==='video'?'видеозвонок':'голосовой звонок');$('callOverlay').classList.remove('hidden');$('endCall').textContent='✕';$('endCall').onclick=()=>{send({t:'call-reject',to:callPeer,callId});closeCallUI('Вызов отклонён')};$('closeCall').onclick=()=>{send({t:'call-reject',to:callPeer,callId});closeCallUI('Вызов отклонён')};$('muteCall').textContent='✓ Принять';$('muteCall').style.width='auto';$('muteCall').style.borderRadius='18px';$('muteCall').style.padding='0 16px';$('cameraCall').classList.add('hidden');playPulseSound('call',true);}
async function answerCall(m){if(!pc||!callInitiator)return;try{await pc.setRemoteDescription(new RTCSessionDescription(m.answer));for(const c of pendingCandidates)await pc.addIceCandidate(new RTCIceCandidate(c));pendingCandidates=[]}catch(e){toast('Ошибка установки соединения: '+e.message)}}
async function toggleMute(){if(!callInitiator&&callPeer&&!pc){stopPulseSound('call');try{localStream=await navigator.mediaDevices.getUserMedia({audio:true,video:callType==='video'});$('localVideo').srcObject=localStream;$('localVideo').classList.toggle('hidden',callType!=='video');pc=createPeer();for(const t of localStream.getTracks())pc.addTrack(t,localStream);await pc.setRemoteDescription(new RTCSessionDescription(window.incomingOffer));for(const c of pendingCandidates)await pc.addIceCandidate(new RTCIceCandidate(c));pendingCandidates=[];const answer=await pc.createAnswer();await pc.setLocalDescription(answer);send({t:'call-answer',to:callPeer,answer,callId});callInitiator=true;$('callState').textContent='Подключаемся…';$('muteCall').textContent='🎙';$('muteCall').style.width='53px';$('muteCall').style.borderRadius='50%';$('muteCall').style.padding='0';$('cameraCall').classList.toggle('hidden',callType!=='video');$('endCall').textContent='☎';$('endCall').onclick=()=>endCall(true);$('closeCall').onclick=()=>endCall(true);return}catch(e){toast('Не удалось принять звонок: '+e.message);closeCallUI('Ошибка подключения');return}}micMuted=!micMuted;localStream?.getAudioTracks().forEach(t=>t.enabled=!micMuted);$('muteCall').textContent=micMuted?'🔇':'🎙'}
