function endCall(notifyPeer){if(notifyPeer&&callPeer)send({t:'call-end',to:callPeer,callId,startedAt:callStartedAt,callType});closeCallUI('Звонок завершён')}
function closeCallUI(state){stopPulseSound('call');if(pc){pc.close();pc=null}if(localStream){localStream.getTracks().forEach(t=>t.stop());localStream=null}$('remoteVideo').srcObject=null;$('localVideo').srcObject=null;$('remoteVideoWrap').classList.add('hidden');$('localVideo').classList.add('hidden');$('callOverlay').classList.add('hidden');$('callState').textContent=state||'';$('muteCall').textContent='🎙';$('muteCall').style.width='53px';$('muteCall').style.borderRadius='50%';$('muteCall').style.padding='0';$('cameraCall').classList.remove('hidden');$('endCall').textContent='☎';$('endCall').onclick=()=>endCall(true);$('closeCall').onclick=()=>endCall(true);callPeer=null;callInitiator=false;callId=null;callStartedAt=0;pendingCandidates=[]}

function urlBase64ToBytes(value){const pad='='.repeat((4-value.length%4)%4),raw=atob((value+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function updatePushButton(){const btn=$('pushNotifications'),status=$('pushNotificationStatus');if(!btn||!status)return;if(!('serviceWorker'in navigator)||!('PushManager'in window)){btn.disabled=true;status.textContent='Пуш-уведомления не поддерживаются этим браузером';return}try{const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();btn.textContent=sub?'Отключить пуш-уведомления':'Включить пуш-уведомления';status.textContent=sub?'Уведомления включены на этом устройстве':'Разреши уведомления, чтобы получать сообщения и подарки';btn.disabled=false}catch{status.textContent='Не удалось проверить push-подписку'}}
async function togglePushNotifications(){const btn=$('pushNotifications'),status=$('pushNotificationStatus');if(!btn||btn.disabled)return;btn.disabled=true;try{if(!('serviceWorker'in navigator)||!('PushManager'in window))throw new Error('Этот браузер не поддерживает пуш-уведомления');const reg=await navigator.serviceWorker.register('/sw.js');let sub=await reg.pushManager.getSubscription();if(sub){const r=await fetch('/api/push/subscribe',{method:'DELETE',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({endpoint:sub.endpoint})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Не удалось отключить уведомления');await sub.unsubscribe();status.textContent='Пуш-уведомления отключены';btn.textContent='Включить пуш-уведомления';toast('Уведомления отключены');return}const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('Разреши уведомления в настройках браузера');const kr=await fetch('/api/push/public-key',{credentials:'same-origin'}),kd=await kr.json();if(!kr.ok||!kd.publicKey)throw new Error(kd.error||'Не удалось получить ключ уведомлений');sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToBytes(kd.publicKey)});const r=await fetch('/api/push/subscribe',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify({subscription:sub.toJSON()})}),d=await r.json();if(!r.ok){await sub.unsubscribe();throw new Error(d.error||'Не удалось сохранить подписку')}status.textContent='Пуш-уведомления включены ✓';btn.textContent='Отключить пуш-уведомления';toast('Пуш-уведомления включены 🔔')}catch(e){status.textContent=e.message||'Не удалось настроить уведомления';toast(status.textContent)}finally{btn.disabled=false}}
async function reactToPost(id,emoji){try{const r=await fetch('/api/posts/'+encodeURIComponent(id)+'/react',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',cache:'no-store',body:JSON.stringify({emoji})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Не удалось поставить реакцию');if(!d.post||d.post.id!==id)throw new Error('Сервер не подтвердил реакцию');const i=newsPosts.findIndex(p=>p.id===d.post.id);if(i>=0)newsPosts[i]=d.post;else newsPosts.unshift(d.post);renderList()}catch(e){toast(e.message||'Ошибка реакции')}}
async function cookieRequest(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:{},credentials:'same-origin',body:body?JSON.stringify(body):undefined}),d=await r.json();if(!r.ok)throw new Error(d.error||'Ошибка печеньки');return d}
async function loadCookieStatus(){try{const d=await cookieRequest('/api/cookie/status');cookieStats={clicks:d.clicks||0,pulses:d.pulses||0};cookieCaptcha=d.captchaRequired?{question:d.question||'Реши пример'}:null;renderCookieBot()}catch(e){toast(e.message)}}
function renderCookieBot(){const el=$('messages');if(!el)return;const clicks=Number(cookieStats.clicks)||0,progress=clicks%30;el.innerHTML='<div class="cookie-game"><div class="cookie-game-kicker">PULSE MINI GAME</div><h2>🍪 Печенька</h2><p>Нажимай на печеньку: каждые <b>30 кликов</b> начисляется <b>1 Пульс ⚡</b>.</p><button class="cookie-big" data-cookie-click aria-label="Кликнуть печеньку">🍪<span>КЛИК!</span></button><div class="cookie-stats"><div><small>Всего кликов</small><b>'+clicks.toLocaleString('ru-RU')+'</b></div><div><small>До Пульса</small><b>'+(30-progress===30?30:30-progress)+'</b></div><div><small>Баланс</small><b>'+Number(cookieStats.pulses||0).toLocaleString('ru-RU')+' ⚡</b></div></div><div class="cookie-progress"><i style="width:'+(progress/30*100)+'%"></i></div>'+(cookieCaptcha?'<div class="cookie-captcha"><b>🛡️ Проверка каждые 300 кликов</b><p>'+esc(cookieCaptcha.question)+'</p><div><input id="cookieCaptchaAnswer" inputmode="numeric" placeholder="Ответ" maxlength="3"><button data-cookie-captcha-submit>Проверить</button></div><small>После проверки продолжишь зарабатывать Пульсы.</small></div>':'<small class="muted">Следующая проверка — на 300, 600, 900… кликах.</small>')+'</div>';el.scrollTop=el.scrollHeight}
async function clickCookie(){try{const d=await cookieRequest('/api/cookie/click',{click:true});cookieStats={clicks:d.clicks||0,pulses:d.pulses||0};cookieCaptcha=d.captchaRequired?{question:d.question||'Реши пример'}:null;renderCookieBot();if(d.awarded)toast('+1 Пульс ⚡');}catch(e){toast(e.message)}}
